redate(sheet: string, id: number, date: string): Promise<Claim> {
  return firstValueFrom(
    this.http.post<Claim>(`${this.url(sheet)}/claims/${id}/redate`, { date }, {
      headers: this.session.headers(),
    }),
  );
}

